sql_query:
SELECT o.market AS MARKET,
       SUM(o.sales) AS total_sales
FROM tiger_data_engineering.global_superstore_gold.gold_orders o
WHERE o.region = {{region}}
  AND o.segment = {{segment}}
  AND o.order_date BETWEEN {{start_date}} AND {{end_date}}
GROUP BY o.market
ORDER BY SUM(o.sales) DESC
